#[test]
fn profile_key_and_prefix_known_answers() {
    assert_eq!(crate::params::PROFILE_ID, b"PZSP5-R5-N0001");
    let pk = hex(PK);
    let seed: &[u8; 32] = pk[pk.len() - 32..].try_into().unwrap();
    assert_eq!(
        crate::dither_frame::expand(&pk[14..2126], seed).unwrap(),
        DELTA
    );
    let prefixes = PublicPrefixes::new(&pk[14..]);
    let mu = prefixes.message_rep(b"", b"");
    assert_eq!(mu.as_slice(), hex(MU));
    assert_eq!(prefixes.verify_message_rep(b"", b""), mu);
    let salt: [u8; 32] = hex(SALT).try_into().unwrap();
    let labels = hex(LABELS);
    assert_eq!(
        prefixes.challenge_bytes(&mu, &salt, &labels).as_slice(),
        hex(CHALLENGE)
    );
    assert_eq!(
        prefixes
            .verify_challenge_bytes(&mu, &salt, &labels)
            .as_slice(),
        hex(CHALLENGE)
    );
    let key_seed: [u8; 64] = core::array::from_fn(|i| i as u8);
    assert_eq!(
        Xof::new(
            crate::params::DOM_KEY,
            &[crate::params::PROFILE_ID, &key_seed]
        )
        .bytes::<64>()
        .as_slice(),
        hex(KEY_STREAM)
    );
    for tag in [
        b"PZRL5-R5-N0001",
        b"PZRS1-R5-N0001",
        b"PZLF3-R5-N0001",
        b"PZW75Q64F10V01",
    ] {
        let mut wrong = pk.clone();
        wrong[..14].copy_from_slice(tag);
        crate::direct_ntt_profile::without_expansion(|| assert!(PreparedPk::new(&wrong).is_err()));
    }
}
#[test]
fn public_release_paths_match_recorded_answers() {
    let ctx = Ctx::new();
    let pk = PreparedPk::new(&hex(PK)).unwrap();
    let signature = hex(SIG);
    assert_eq!(signature.len(), 1908);
    let verifier = crate::scheme::verifier::PreparedVerifier::new(&ctx).unwrap();
    verifier.verify(&pk, b"", b"", &signature).unwrap();
    verifier
        .verify_reference(&pk, b"", b"", &signature)
        .unwrap();
    verifier
        .verify_serialized_complete(&hex(PK), b"", b"", &signature)
        .unwrap();
    assert!(verifier.verify(&pk, b"wrong", b"", &signature).is_err());
    assert!(verifier.verify(&pk, b"", b"wrong", &signature).is_err());
    for (position, count) in [(1504usize, 41u8), (1885, 17)] {
        let mut bad = signature.clone();
        bad[position] = count;
        assert!(verifier.verify(&pk, b"", b"", &bad).is_err());
        assert!(verifier.verify_reference(&pk, b"", b"", &bad).is_err());
    }
}
